import localFont from "next/font/local";

// Latin subsets of Google Fonts, regenerated by `npm run fonts`. Self-hosted so
// the build never depends on fetching from Google.
const epilogue = localFont({
  src: [
    { path: "./fonts/epilogue.woff2", weight: "400 900", style: "normal" },
    { path: "./fonts/epilogue-italic.woff2", weight: "400 900", style: "italic" },
  ],
  variable: "--font-epilogue",
});

const jakarta = localFont({
  src: "./fonts/plus-jakarta-sans.woff2",
  weight: "400 600",
  variable: "--font-jakarta",
});

const grotesk = localFont({
  src: "./fonts/space-grotesk.woff2",
  weight: "600",
  variable: "--font-grotesk",
});

/** Subset of Material Symbols regenerated by `npm run icons`. */
const icons = localFont({
  src: "./fonts/material-symbols-outlined.woff2",
  variable: "--font-icons",
  display: "block",
});

/** Font CSS variables for <html>, shared by the root layout and the global error page. */
export const FONT_VARIABLES = [epilogue, jakarta, grotesk, icons]
  .map((font) => font.variable)
  .join(" ");
